import React from "react";
import { useAppContext, actions } from "../context/AppContext";

const ControlPanel = () => {
  const { state, dispatch } = useAppContext();

  const handleTextureChange = (texture) => {
    dispatch(actions.setEarthTexture(texture));
  };

  const handleRotationSpeedChange = (event) => {
    const speed = parseFloat(event.target.value);
    dispatch(actions.setRotationSpeed(speed));
  };

  const handleZoomChange = (event) => {
    const zoom = parseFloat(event.target.value);
    dispatch(actions.setCameraZoom(zoom));
  };

  if (!state.ui.showControls) {
    return (
      <button
        onClick={() => dispatch(actions.toggleControls())}
        className="fixed top-4 left-4 z-50 bg-space-blue bg-opacity-80 hover:bg-opacity-100 text-white p-3 rounded-lg transition-all duration-300 backdrop-blur-sm"
        title="Show Controls"
      >
        <svg
          className="w-6 h-6"
          fill="none"
          stroke="currentColor"
          viewBox="0 0 24 24"
        >
          <path
            strokeLinecap="round"
            strokeLinejoin="round"
            strokeWidth={2}
            d="M12 6V4m0 2a2 2 0 100 4m0-4a2 2 0 110 4m-6 8a2 2 0 100-4m0 4a2 2 0 100 4m0-4v2m0-6V4m6 6v10m6-2a2 2 0 100-4m0 4a2 2 0 100 4m0-4v2m0-6V4"
          />
        </svg>
      </button>
    );
  }

  return (
    <div className="fixed top-4 left-4 z-50 bg-space-blue bg-opacity-90 text-white p-6 rounded-xl shadow-2xl backdrop-blur-md max-w-sm">
      {/* Header */}
      <div className="flex items-center justify-between mb-6">
        <h2 className="text-xl font-bold">Earth Controls</h2>
        <button
          onClick={() => dispatch(actions.toggleControls())}
          className="text-gray-300 hover:text-white transition-colors"
          title="Hide Controls"
        >
          <svg
            className="w-5 h-5"
            fill="none"
            stroke="currentColor"
            viewBox="0 0 24 24"
          >
            <path
              strokeLinecap="round"
              strokeLinejoin="round"
              strokeWidth={2}
              d="M6 18L18 6M6 6l12 12"
            />
          </svg>
        </button>
      </div>

      {/* Animation Controls */}
      <div className="space-y-4 mb-6">
        <h3 className="text-lg font-semibold text-blue-300">Animation</h3>

        <div className="flex items-center justify-between">
          <span className="text-sm">Auto Rotate</span>
          <button
            onClick={() => dispatch(actions.toggleAutoRotate())}
            className={`relative inline-flex h-6 w-11 items-center rounded-full transition-colors ${
              state.camera.autoRotate ? "bg-blue-600" : "bg-gray-600"
            }`}
          >
            <span
              className={`inline-block h-4 w-4 transform rounded-full bg-white transition-transform ${
                state.camera.autoRotate ? "translate-x-6" : "translate-x-1"
              }`}
            />
          </button>
        </div>

        <div>
          <label className="block text-sm mb-2">
            Rotation Speed: {state.camera.rotationSpeed.toFixed(3)}
          </label>
          <input
            type="range"
            min="0"
            max="0.05"
            step="0.001"
            value={state.camera.rotationSpeed}
            onChange={handleRotationSpeedChange}
            className="w-full h-2 bg-gray-700 rounded-lg appearance-none cursor-pointer slider"
          />
        </div>

        <div>
          <label className="block text-sm mb-2">
            Zoom: {state.camera.zoom.toFixed(1)}x
          </label>
          <input
            type="range"
            min="0.5"
            max="3"
            step="0.1"
            value={state.camera.zoom}
            onChange={handleZoomChange}
            className="w-full h-2 bg-gray-700 rounded-lg appearance-none cursor-pointer slider"
          />
        </div>
      </div>

      {/* Texture Controls */}
      <div className="space-y-4 mb-6">
        <h3 className="text-lg font-semibold text-blue-300">Textures</h3>

        <div className="grid grid-cols-2 gap-2">
          {[
            { key: "day", label: "Day", emoji: "🌍" },
            { key: "night", label: "Night", emoji: "🌃" },
            { key: "bump", label: "Bump", emoji: "🏔️" },
            { key: "clouds", label: "Clouds", emoji: "☁️" },
          ].map(({ key, label, emoji }) => (
            <button
              key={key}
              onClick={() => handleTextureChange(key)}
              className={`p-3 rounded-lg transition-all duration-200 ${
                state.earth.texture === key
                  ? "bg-blue-600 shadow-lg transform scale-105"
                  : "bg-gray-700 hover:bg-gray-600"
              }`}
            >
              <div className="text-lg mb-1">{emoji}</div>
              <div className="text-xs">{label}</div>
            </button>
          ))}
        </div>
      </div>

      {/* Display Options */}
      <div className="space-y-4">
        <h3 className="text-lg font-semibold text-blue-300">Display</h3>

        <div className="space-y-3">
          <div className="flex items-center justify-between">
            <span className="text-sm">Show Earth</span>
            <button
              onClick={() => dispatch(actions.toggleEarthVisibility())}
              className={`relative inline-flex h-6 w-11 items-center rounded-full transition-colors ${
                state.earth.visible ? "bg-blue-600" : "bg-gray-600"
              }`}
            >
              <span
                className={`inline-block h-4 w-4 transform rounded-full bg-white transition-transform ${
                  state.earth.visible ? "translate-x-6" : "translate-x-1"
                }`}
              />
            </button>
          </div>

          <div className="flex items-center justify-between">
            <span className="text-sm">Wireframe</span>
            <button
              onClick={() => dispatch(actions.toggleWireframe())}
              className={`relative inline-flex h-6 w-11 items-center rounded-full transition-colors ${
                state.earth.wireframe ? "bg-blue-600" : "bg-gray-600"
              }`}
            >
              <span
                className={`inline-block h-4 w-4 transform rounded-full bg-white transition-transform ${
                  state.earth.wireframe ? "translate-x-6" : "translate-x-1"
                }`}
              />
            </button>
          </div>

          <div className="flex items-center justify-between">
            <span className="text-sm">Countries</span>
            <button
              onClick={() => dispatch(actions.toggleCountriesVisibility())}
              className={`relative inline-flex h-6 w-11 items-center rounded-full transition-colors ${
                state.countries.visible ? "bg-blue-600" : "bg-gray-600"
              }`}
            >
              <span
                className={`inline-block h-4 w-4 transform rounded-full bg-white transition-transform ${
                  state.countries.visible ? "translate-x-6" : "translate-x-1"
                }`}
              />
            </button>
          </div>
        </div>
      </div>

      {/* Action Buttons */}
      <div className="mt-6 pt-4 border-t border-gray-600 flex gap-2">
        <button
          onClick={() => dispatch(actions.toggleSettings())}
          className="flex-1 bg-gray-700 hover:bg-gray-600 text-white py-2 px-4 rounded-lg transition-colors text-sm"
        >
          Settings
        </button>
        <button
          onClick={() => dispatch(actions.toggleRecording())}
          className={`flex-1 py-2 px-4 rounded-lg transition-colors text-sm ${
            state.ui.isRecording
              ? "bg-red-600 hover:bg-red-700 text-white"
              : "bg-green-600 hover:bg-green-700 text-white"
          }`}
        >
          {state.ui.isRecording ? "⏹ Stop" : "🔴 Record"}
        </button>
      </div>
    </div>
  );
};

export default ControlPanel;
